const state={user:null,clients:[],products:[],quotes:[],sales:[],salesFilter:'All',settings:{},reportPeriod:'month',reportStart:'',reportEnd:'',reportClient:'All',reportPayment:'All',reportSource:'All',users:[],audit:[],page:'dashboard',search:'',filter:'All',quoteSort:'newest'};const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),money=n=>`${esc(state.settings.currency||'PKR')} ${Number(n||0).toLocaleString('en-PK',{minimumFractionDigits:2,maximumFractionDigits:2})}`;function toast(t){let e=$('#toast');e.textContent=t;e.classList.add('show');setTimeout(()=>e.classList.remove('show'),2700)}async function api(url,options={}){let r=await fetch(url,{credentials:'same-origin',...options,headers:{'Content-Type':'application/json',...(options.headers||{})}}),d;try{d=await r.json()}catch{d={error:'Invalid server response'}}if(!r.ok)throw Error(d.error||`Request failed (${r.status})`);return d}
async function loadAll(){let names=['clients','products','quotes','settings','sales'],requests=await Promise.allSettled([api('/api/clients'),api('/api/products'),api('/api/quotations'),api('/api/settings'),api('/api/sales')]),issues=[];for(let i=0;i<names.length;i++){let r=requests[i];state[names[i]]=r.status==='fulfilled'?r.value:(names[i]==='settings'?{}:[]);if(r.status==='rejected')issues.push(`${names[i]}: ${r.reason.message}`)}if(state.user.role==='Administrator'){for(let [key,url] of [['users','/api/users'],['audit','/api/audit']])try{state[key]=await api(url)}catch(e){state[key]=[];issues.push(`${key}: ${e.message}`)}}$('#companyLabel').textContent=state.settings.company||'Business workspace';$('#quoteCount').textContent=state.quotes.length;$('#saleCount').textContent=state.sales.length;$('#userLabel').textContent=state.user.name;$('#roleLabel').textContent=state.user.role;$('#headerUser').textContent=state.user.name;$('#headerRole').textContent=state.user.role;document.querySelectorAll('.admin-only').forEach(x=>x.hidden=state.user.role!=='Administrator');document.querySelectorAll('.header-new').forEach(x=>x.hidden=state.user.role==='Viewer');render();if(issues.length)$('#page').insertAdjacentHTML('afterbegin',`<div class="note" style="margin-bottom:16px"><b>Some records did not load.</b> ${esc(issues.join(' · '))} <button class="btn mini" onclick="loadAll()">Retry</button></div>`)}
let setupNeeded=false,authView='login';async function boot(){try{let d=await api('/api/auth/me');state.user=d.user;$('#shell').hidden=false;await loadAll()}catch{try{setupNeeded=(await api('/api/auth/setup-status')).needed;authView=setupNeeded?'signup':'login';showLogin()}catch{setupNeeded=false;authView='login';showLogin('Cannot reach the FrameFlow server. Start Restart-FrameFlow.cmd and refresh this page.')}}}
function showLogin(error=''){const signup=authView==='signup';$('#shell').hidden=true;$('#login').hidden=false;$('#login').innerHTML=`<form class="login-card" id="authForm"><div class="logo">F</div><div class="eyebrow" style="margin-top:17px">FRAMEFLOW · QUOTATION STUDIO</div><h1>${setupNeeded?'Set up your workspace':signup?'Create your account':'Sign in'}</h1><p class="subtitle">${setupNeeded?'Create the first administrator account.':signup?'Request access to your business workspace.':'Use your business account.'}</p>${error?`<div class="${error.startsWith('Signup received.')?'login-success':'login-error'}" role="status">${esc(error)}</div>`:''}${signup?`<div class="field"><label>Your name</label><input class="input" name="name" autocomplete="name" maxlength="120" required></div>`:''}<div class="field"><label>Email</label><input class="input" name="email" type="email" autocomplete="username" required></div><div class="field"><label>Password ${signup?'(12+ characters)':''}</label><input class="input" name="password" type="password" minlength="${signup?12:1}" maxlength="256" autocomplete="${signup?'new-password':'current-password'}" required></div>${signup?`<div class="field"><label>Confirm password</label><input class="input" name="confirm" type="password" minlength="12" maxlength="256" autocomplete="new-password" required></div>`:''}<button class="btn primary" style="width:100%;margin-top:18px">${setupNeeded?'Create administrator':signup?'Request account':'Sign in'}</button><p class="login-foot">${setupNeeded?'Your first account is the workspace administrator.':signup?'New accounts need administrator approval before sign-in.':''}</p>${!setupNeeded?`<button class="auth-switch" type="button" id="authSwitch">${signup?'Already have an account? Sign in':'Need an account? Sign up'}</button>`:''}</form>`;$('#authForm').onsubmit=signup?createAccount:login;$('#authSwitch')?.addEventListener('click',()=>{authView=signup?'login':'signup';showLogin()})}
async function login(e){e.preventDefault();let f=new FormData(e.target),d;try{d=await api('/api/auth/login',{method:'POST',body:JSON.stringify({email:f.get('email'),password:f.get('password')})})}catch(err){return showLogin(err.message)}state.user=d.user;$('#login').hidden=true;$('#shell').hidden=false;await loadAll()}
async function createAccount(e){e.preventDefault();let f=new FormData(e.target);if(f.get('password')!==f.get('confirm'))return showLogin('Passwords do not match');let d;try{d=await api(setupNeeded?'/api/auth/setup':'/api/auth/signup',{method:'POST',body:JSON.stringify({name:f.get('name'),email:f.get('email'),password:f.get('password')})})}catch(err){return showLogin(err.message)}if(setupNeeded){state.user=d.user;setupNeeded=false;$('#login').hidden=true;$('#shell').hidden=false;await loadAll();return}showLogin('Signup received. An administrator must approve the account before you can sign in.')}
function nav(p){state.page=p;state.search='';state.filter='All';document.querySelectorAll('.nav').forEach(x=>x.classList.toggle('active',x.dataset.page===p));$('#crumb').textContent=({dashboard:'Overview',quotes:'Quotations',sales:'Sales',reports:'Reports',clients:'Clients',catalog:'Catalog & rates',users:'Users & audit',settings:'Settings'})[p];render()}document.querySelectorAll('.nav').forEach(x=>x.onclick=()=>nav(x.dataset.page));function title(k,t,s,b=''){return `<div class="title-row"><div><div class="eyebrow">${k}</div><h1>${t}</h1><div class="subtitle">${s}</div></div>${b}</div>`}function button(a,label,cls=''){return `<button class="btn ${cls}" data-action="${a}">${label}</button>`}function status(s){return `<span class="status ${esc(s)}">${esc(s)}</span>`}function qrows(arr){return arr.length?arr.map(q=>`<tr><td><div class="primary-cell">${esc(q.number)}</div><div class="secondary">${esc(q.created_at?.slice(0,10)||'')}</div></td><td>${esc(q.client_name)}</td><td>${q.items.length} item${q.items.length===1?'':'s'}</td><td>${money(q.total)}</td><td>${status(q.status)}</td><td><div class="small-actions"><button class="btn mini" data-action="view-quote" data-id="${q.id}">View</button><button class="btn mini" data-action="pdf" data-id="${q.id}">Print</button></div></td></tr>`).join(''):`<tr><td colspan="6"><div class="empty">No quotations yet</div></td></tr>`}function render(){let p=$('#page');if(state.page==='dashboard')p.innerHTML=dashboard();if(state.page==='quotes')p.innerHTML=quotesPage();if(state.page==='sales')p.innerHTML=salesPage();if(state.page==='reports')p.innerHTML=reportsPage();if(state.page==='clients')p.innerHTML=clientsPage();if(state.page==='catalog')p.innerHTML=catalogPage();if(state.page==='settings')p.innerHTML=settingsPage();if(state.page==='users')p.innerHTML=usersPage()}function dashboard(){let qs=[...state.quotes].sort((a,b)=>b.created_at.localeCompare(a.created_at)),approved=qs.filter(x=>x.status==='Approved').reduce((s,x)=>s+Number(x.total),0),drafts=qs.filter(x=>x.status==='Draft').length,issued=qs.filter(x=>x.status==='Issued').length,first=(state.user.name||'there').trim().split(/\s+/)[0];return `<div class="dashboard-hero"><div><div class="eyebrow">YOUR WORKSPACE · ${new Date().toLocaleDateString('en',{weekday:'long',month:'long',day:'numeric'}).toUpperCase()}</div><h1>Welcome back, ${esc(first)}</h1><p class="subtitle">Here’s what’s happening with your quotations today.</p><div class="shortcut-hints"><span><kbd>Alt</kbd> <b>+</b> <kbd>N</kbd> New quotation</span><span><kbd>/</kbd> Search this page</span><span><kbd>Esc</kbd> Close dialog</span></div></div><div class="hero-actions">${state.user.role==='Viewer'?'':button('new-quote','＋ &nbsp;Create quotation','primary')}<button class="btn hero-secondary" data-goto="clients">View clients <span>→</span></button></div></div><div class="stat-grid"><div class="card stat"><div class="stat-top"><span>Total quotations</span><span class="stat-icon">▤</span></div><div class="stat-value">${qs.length}</div><div class="stat-foot">Across all statuses</div></div><div class="card stat"><div class="stat-top"><span>Drafts to finish</span><span class="stat-icon amber">✎</span></div><div class="stat-value">${drafts}</div><div class="stat-foot">Ready for review</div></div><div class="card stat"><div class="stat-top"><span>Awaiting response</span><span class="stat-icon violet">◷</span></div><div class="stat-value">${issued}</div><div class="stat-foot">Sent to your clients</div></div><div class="card stat"><div class="stat-top"><span>Approved value</span><span class="stat-icon mint">↗</span></div><div class="stat-value money-stat">${money(approved)}</div><div class="stat-foot">${qs.filter(x=>x.status==='Approved').length} approved quotations</div></div></div><div class="dashboard-grid"><div class="card section-card recent-card"><div class="section-head"><div><div class="eyebrow">SALES ACTIVITY</div><h2>Recent quotations</h2><p>Your latest saved customer offers</p></div><a class="link" data-goto="quotes">View all <span>→</span></a></div><div class="table-wrap"><table><thead><tr><th>Quote</th><th>Client</th><th>Items</th><th>Total</th><th>Status</th><th></th></tr></thead><tbody>${qrows(qs.slice(0,6))}</tbody></table></div></div><div class="dashboard-rail"><div class="card section-card quick-card"><div class="eyebrow">SHORTCUTS</div><h2>Quick actions</h2><button class="quick-action" data-action="new-quote"><span class="quick-icon">＋</span><span><b>Start a quotation</b><small>Prepare a new customer offer</small></span><span class="quick-arrow">→</span></button><button class="quick-action" data-goto="clients"><span class="quick-icon people">♙</span><span><b>Manage clients</b><small>${state.clients.length} contacts in your workspace</small></span><span class="quick-arrow">→</span></button><button class="quick-action" data-goto="catalog"><span class="quick-icon catalog">▧</span><span><b>Check product rates</b><small>${state.products.length.toLocaleString()} active catalog items</small></span><span class="quick-arrow">→</span></button></div><div class="workspace-tip"><div class="tip-mark">✦</div><div><b>Rates stay consistent</b><p>Issued quotations keep their saved prices, even when your catalog rates change.</p></div></div></div></div>`}
function toolbar(ph,filters=false){return `<div class="toolbar"><input id="search" class="input search" placeholder="⌕  ${ph}" value="${esc(state.search)}">${filters?`<select id="statusFilter" class="input select">${['All','Draft','Issued','Approved','Closed','Rejected','Expired'].map(x=>`<option ${state.filter===x?'selected':''}>${x}</option>`).join('')}</select>`:''}<span style="flex:1"></span>${state.user.role==='Administrator'?button('export','↓ Export CSV'):''}</div>`}function quoteTableRows(arr){return arr.length?arr.map(q=>{let preview=(q.items||[]).slice(0,2).map(i=>i.product_name).join(', '),more=(q.items||[]).length-2;return `<tr><td><div class="quote-number">${esc(q.number)}</div><div class="secondary">${esc(q.created_at?.slice(0,10)||'')}</div></td><td><div class="primary-cell">${esc(q.client_name)}</div><div class="secondary">${esc(q.client_phone||'No phone')}</div></td><td><div class="quote-item-count">${q.items.length} item${q.items.length===1?'':'s'}</div><div class="secondary quote-item-preview">${esc(preview||'No items')}${more>0?` +${more} more`:''}</div></td><td><div class="quote-total">${money(q.total)}</div></td><td>${status(q.status)}${q.valid_until?`<div class="secondary quote-validity">Valid to ${esc(q.valid_until)}</div>`:''}</td><td><div class="small-actions"><button class="btn mini" data-action="view-quote" data-id="${q.id}">View</button><button class="btn mini" data-action="pdf" data-id="${q.id}">PDF</button></div></td></tr>`}).join(''):`<tr><td colspan="6"><div class="empty quote-no-results"><strong>${state.search||state.filter!=='All'?'No matching quotations':'No quotations yet'}</strong>${state.search||state.filter!=='All'?'Try changing the search or status filter.':'Create your first quotation to see it here.'}</div></td></tr>`}function quotesPage(){let term=state.search.toLowerCase().trim(),qs=state.quotes.filter(q=>(state.filter==='All'||(state.filter==='Closed'?['Rejected','Expired'].includes(q.status):q.status===state.filter))&&(!term||[q.number,q.client_name,q.client_phone,q.status,...(q.items||[]).map(i=>`${i.product_name} ${i.code||''}`)].join(' ').toLowerCase().includes(term)));let sorters={newest:(a,b)=>b.created_at.localeCompare(a.created_at),oldest:(a,b)=>a.created_at.localeCompare(b.created_at),highest:(a,b)=>Number(b.total)-Number(a.total),lowest:(a,b)=>Number(a.total)-Number(b.total)};qs.sort(sorters[state.quoteSort]||sorters.newest);let counts={All:state.quotes.length,Draft:state.quotes.filter(q=>q.status==='Draft').length,Issued:state.quotes.filter(q=>q.status==='Issued').length,Approved:state.quotes.filter(q=>q.status==='Approved').length,Closed:state.quotes.filter(q=>['Rejected','Expired'].includes(q.status)).length},tools=toolbar('Search quote, client, phone, item, or status',true).replace('</select>', `</select><select id="quoteSort" class="input select quote-sort" aria-label="Sort quotations"><option value="newest" ${state.quoteSort==='newest'?'selected':''}>Newest first</option><option value="oldest" ${state.quoteSort==='oldest'?'selected':''}>Oldest first</option><option value="highest" ${state.quoteSort==='highest'?'selected':''}>Highest total</option><option value="lowest" ${state.quoteSort==='lowest'?'selected':''}>Lowest total</option></select>`),filters=['All','Draft','Issued','Approved','Closed'].map(k=>`<button class="quote-filter ${state.filter===k?'active':''}" data-quote-filter="${k}" aria-pressed="${state.filter===k}"><span>${k}</span><b>${counts[k]}</b></button>`).join('');return `${title('SALES WORKSPACE','Quotations','Find, review and follow every customer offer.',state.user.role==='Viewer'?'':button('new-quote','＋ &nbsp;New quotation','primary'))}<div class="quote-filters" aria-label="Filter quotations by status">${filters}</div><div class="card page-card quote-list-card">${tools}<div class="quote-results"><span>${qs.length} of ${state.quotes.length} quotations</span>${term||state.filter!=='All'?`<button class="quote-clear" data-quote-filter="All">Clear status filter</button>`:''}</div><div class="table-pad"><table><thead><tr><th>Quotation</th><th>Client</th><th>Items</th><th>Total</th><th>Status / validity</th><th>Actions</th></tr></thead><tbody>${quoteTableRows(qs)}</tbody></table></div></div>`}function visibleSales(){let term=state.search.toLowerCase().trim();return state.sales.filter(s=>(state.salesFilter==='All'||s.payment_status===state.salesFilter)&&(!term||[s.number,s.client_name,s.quotation_number,s.payment_status].join(' ').toLowerCase().includes(term))).sort((a,b)=>(b.sold_at||'').localeCompare(a.sold_at||''))}
function salesRows(rows){return rows.length?rows.map(s=>`<tr><td><div class="quote-number">${esc(s.number)}</div><div class="secondary">${esc(s.sold_at?.slice(0,10)||'')}</div></td><td><div class="primary-cell">${esc(s.client_name)}</div></td><td>${s.quotation_number?`${esc(s.quotation_number)}<div class="secondary">Rev. ${s.revision}</div>`:'Direct sale'}</td><td>${(s.items||[]).length}</td><td><b>${money(s.total)}</b></td><td>${money(s.amount_paid)}</td><td>${money(Number(s.total)-Number(s.amount_paid))}</td><td>${status(s.payment_status)}</td><td><div class="small-actions"><button class="btn mini" data-action="view-sale" data-id="${s.id}">Details</button><button class="btn mini" data-action="record-payment" data-id="${s.id}">Payment</button></div></td></tr>`).join(''):`<tr><td colspan="9"><div class="empty"><strong>${state.search||state.salesFilter!=='All'?'No matching sales':'No sales recorded yet'}</strong>${state.search||state.salesFilter!=='All'?'Try another search or payment status.':'Convert an approved quotation or record a direct sale.'}</div></td></tr>`}
function salesPage(){let total=state.sales.reduce((sum,s)=>sum+Number(s.total||0),0),paid=state.sales.reduce((sum,s)=>sum+Number(s.amount_paid||0),0),outstanding=total-paid,rows=visibleSales(),actions=`${state.user.role==='Administrator'?button('export-sales','↓ &nbsp;Export CSV'):''}${button('goto-reports','▥ &nbsp;View reports')}${state.user.role==='Viewer'?'':button('new-direct-sale','＋ &nbsp;Direct sale','primary')}`;return `${title('REVENUE WORKSPACE','Sales','Quotation conversions and direct customer sales.',actions)}<div class="sales-summary"><div class="card sales-stat"><span>Recorded sales</span><b>${state.sales.length}</b><small>Converted and direct sales</small></div><div class="card sales-stat"><span>Sales value</span><b>${money(total)}</b><small>All recorded sales</small></div><div class="card sales-stat"><span>Received</span><b>${money(paid)}</b><small>Payments recorded</small></div><div class="card sales-stat"><span>Outstanding</span><b>${money(outstanding)}</b><small>Balance to collect</small></div></div><div class="card page-card sales-table-card"><div class="sales-table-heading"><div><h2>Sales register</h2><p>Each sale preserves its item prices and payment balance.</p></div><span>${rows.length} of ${state.sales.length} sale${state.sales.length===1?'':'s'}</span></div><div class="toolbar sales-toolbar"><input id="search" class="input search" placeholder="⌕  Search sale, client, or quotation" value="${esc(state.search)}"><select id="salesFilter" class="input select" aria-label="Filter sales by payment status">${['All','Unpaid','Partial','Paid'].map(x=>`<option value="${x}" ${state.salesFilter===x?'selected':''}>${x==='All'?'All payment statuses':x}</option>`).join('')}</select></div><div class="table-pad"><table><thead><tr><th>Sale</th><th>Client</th><th>Quotation</th><th>Items</th><th>Total</th><th>Received</th><th>Balance</th><th>Payment</th><th>Actions</th></tr></thead><tbody>${salesRows(rows)}</tbody></table></div></div>`}
function reportDateKey(d){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function reportRange(){let nowDate=new Date(),period=state.reportPeriod,from=new Date(nowDate.getFullYear(),nowDate.getMonth(),1),to=new Date(nowDate.getFullYear(),nowDate.getMonth()+1,0);if(period==='30days'){from=new Date(nowDate);from.setDate(from.getDate()-29);to=nowDate}else if(period==='year'){from=new Date(nowDate.getFullYear(),0,1);to=new Date(nowDate.getFullYear(),11,31)}else if(period==='all'){from=new Date(2000,0,1);to=new Date(2099,11,31)}let start=period==='custom'?(state.reportStart||reportDateKey(from)):reportDateKey(from),end=period==='custom'?(state.reportEnd||reportDateKey(to)):reportDateKey(to);return {start,end}}
function reportMetaMatches(s){return (state.reportClient==='All'||s.client_id===state.reportClient)&&(state.reportPayment==='All'||s.payment_status===state.reportPayment)&&(state.reportSource==='All'||(s.source||'quotation')===state.reportSource)}
function filteredReportSales(){let {start,end}=reportRange();return state.sales.filter(s=>{let d=(s.sold_at||'').slice(0,10);return d>=start&&d<=end&&reportMetaMatches(s)})}
function reportsPage(){let nowDate=new Date(),period=state.reportPeriod,{start,end}=reportRange(),sales=filteredReportSales(),total=sales.reduce((a,s)=>a+Number(s.total||0),0),received=sales.reduce((a,s)=>a+Number(s.amount_paid||0),0),balance=total-received,converted=state.sales.filter(s=>s.source!=='direct'&&s.quotation_id).length,eligible=state.quotes.filter(q=>q.status==='Approved'||state.sales.some(s=>s.quotation_id===q.id)).length,conversion=eligible?Math.min(100,Math.round(converted*100/eligible)):0,months=[];for(let n=5;n>=0;n--){let d=new Date(nowDate.getFullYear(),nowDate.getMonth()-n,1),key=reportDateKey(d).slice(0,7);months.push({key,label:d.toLocaleDateString('en',{month:'short'}),value:state.sales.filter(s=>reportMetaMatches(s)&&(s.sold_at||'').startsWith(key)).reduce((a,s)=>a+Number(s.total||0),0)})}let maxMonth=Math.max(1,...months.map(m=>m.value)),items={};for(let sale of sales)for(let item of sale.items||[]){let key=item.product_name||item.name||'Product';items[key]=(items[key]||0)+Number(item.line_total||0)}let top=Object.entries(items).sort((a,b)=>b[1]-a[1]).slice(0,5),clients=[...new Map(state.sales.map(s=>[s.client_id,s.client_name])).entries()].filter(([id])=>id);return `${title('BUSINESS INSIGHTS','Sales reports','Review revenue with date, customer and payment filters.',state.user.role==='Administrator'?button('export-report','↓ &nbsp;Export filtered CSV'):'')}<div class="report-toolbar card"><label for="reportPeriod">Period</label><select id="reportPeriod" class="input"><option value="month" ${period==='month'?'selected':''}>This month</option><option value="30days" ${period==='30days'?'selected':''}>Last 30 days</option><option value="year" ${period==='year'?'selected':''}>This year</option><option value="all" ${period==='all'?'selected':''}>All time</option><option value="custom" ${period==='custom'?'selected':''}>Custom dates</option></select><label for="reportStart">From</label><input class="input" type="date" id="reportStart" value="${esc(start)}"><label for="reportEnd">To</label><input class="input" type="date" id="reportEnd" value="${esc(end)}"><label for="reportClient">Client</label><select class="input" id="reportClient"><option value="All">All clients</option>${clients.map(([id,name])=>`<option value="${esc(id)}" ${state.reportClient===id?'selected':''}>${esc(name)}</option>`).join('')}</select><label for="reportPayment">Payment</label><select class="input" id="reportPayment">${['All','Unpaid','Partial','Paid'].map(x=>`<option value="${x}" ${state.reportPayment===x?'selected':''}>${x==='All'?'All statuses':x}</option>`).join('')}</select><label for="reportSource">Sale type</label><select class="input" id="reportSource">${[['All','All sale types'],['quotation','Quotation sales'],['direct','Direct sales']].map(([value,label])=>`<option value="${value}" ${state.reportSource===value?'selected':''}>${label}</option>`).join('')}</select><span>${esc(start)} – ${esc(end)} · ${sales.length} sale${sales.length===1?'':'s'}</span></div><div class="report-stats"><div class="card report-stat primary-report"><span>Sales total</span><b>${money(total)}</b><small>${sales.length} matching sale${sales.length===1?'':'s'}</small></div><div class="card report-stat"><span>Payments received</span><b>${money(received)}</b><small>Recorded collections</small></div><div class="card report-stat"><span>Outstanding</span><b>${money(balance)}</b><small>Remaining balances</small></div><div class="card report-stat"><span>Quote conversion</span><b>${conversion}%</b><small>${converted} converted of ${eligible} eligible quotes · all time</small></div></div><div class="report-grid"><div class="card report-card"><div class="report-card-head"><div><h2>Sales by month</h2><p>Last six months · current client, payment and sale-type filters</p></div></div><div class="month-chart">${months.map(m=>`<div class="month-bar-wrap"><div class="month-value">${m.value?money(m.value):'—'}</div><div class="month-bar-track"><div class="month-bar" style="height:${m.value?Math.max(5,Math.round(m.value/maxMonth*100)):0}%"></div></div><small>${m.label}</small></div>`).join('')}</div></div><div class="card report-card"><div class="report-card-head"><div><h2>Top products</h2><p>By line value for filtered sales</p></div></div>${top.length?`<div class="top-products">${top.map(([name,value],i)=>`<div class="top-product"><span class="top-rank">${i+1}</span><span class="top-name">${esc(name)}</span><b>${money(value)}</b></div>`).join('')}</div>`:`<div class="empty report-empty">No sales match these filters.</div>`}</div></div>`}
function paymentModal(sale){modal('Record customer payment',`<div class="payment-context"><b>${esc(sale.client_name)}</b><span>${esc(sale.number)} · Sale total ${money(sale.total)}</span></div><div class="field"><label for="paymentReceived">Total amount received so far (${esc(sale.currency)})</label><input class="input" id="paymentReceived" type="number" min="0" max="${esc(sale.total)}" step="0.01" value="${esc(sale.amount_paid)}"><small>Enter the cumulative amount received. The remaining balance will update automatically.</small></div>`,`${cancel}<button class="btn primary" id="savePayment">Save payment</button>`);$('#savePayment').onclick=async()=>{let btn=$('#savePayment');btn.disabled=true;btn.textContent='Saving…';try{await api('/api/sales/payment',{method:'PATCH',body:JSON.stringify({id:sale.id,amount_paid:$('#paymentReceived').value})});closeModal();await loadAll();toast('Payment updated')}catch(e){btn.disabled=false;btn.textContent='Save payment';toast(e.message)}}}
function directSaleModal(){if(!state.clients.length)return toast('Add a client first');if(!state.products.length)return toast('Add products and rates first');let cOpts=state.clients.map(c=>`<option value="${esc(c.id)}">${esc(c.name)}</option>`).join(''),productOpts=state.products.map(p=>`<option value="${esc(p.name)} · ${esc(p.code)}" label="${esc(p.category)} · ${esc(p.unit)} · ${money(p.rate)}"></option>`).join('');modal('Record direct sale',`<div class="note" style="margin-bottom:14px">Use this when a customer buys without a saved quotation. Prices and items will be saved in this sale record.</div><div class="form-grid"><div class="field"><label>Client *</label><select class="input" id="directClient"><option value="">Select a client</option>${cOpts}</select></div><div class="field"><label>Discount (${esc(state.settings.currency)})</label><input class="input" type="number" id="directDiscount" min="0" step="0.01" value="0"></div></div><div class="quote-items-head"><b>Items</b></div><div class="field quote-product-picker"><label for="directAddProduct">Product</label><input class="input" id="directAddProduct" list="directProductOptions" autocomplete="off" placeholder="Type product name or code to search…"><datalist id="directProductOptions">${productOpts}</datalist></div><div class="item-row item-header"><span>PRODUCT</span><span>QTY</span><span>RATE</span><span>SPECIFICATIONS</span><span></span></div><div id="directItems"><div class="empty quote-empty" id="directEmpty">Choose a product to start this sale.</div></div><div class="total-box"><div class="total-line"><span>Subtotal</span><b id="directSubtotal">${money(0)}</b></div><div class="total-line"><span>Discount</span><b id="directDiscShow">${money(0)}</b></div><div class="total-line final"><span>Total</span><b id="directTotal">${money(0)}</b></div></div><div class="field" style="margin-top:14px"><label for="directPaid">Amount received now (${esc(state.settings.currency)})</label><input class="input" type="number" id="directPaid" min="0" step="0.01" value="0"><small>Leave at 0 if the customer has not paid yet.</small></div>`,`${cancel}<button class="btn primary" id="saveDirectSale">Record sale</button>`);let add=()=>{let input=$('#directAddProduct'),value=input.value.trim().toLocaleLowerCase(),p=state.products.find(x=>x.code.toLocaleLowerCase()===value||`${x.name} · ${x.code}`.toLocaleLowerCase()===value);if(!p){if(value)toast('Choose a product from the catalog suggestions');return}$('#directEmpty')?.remove();$('#directItems').insertAdjacentHTML('beforeend',itemRow({product_id:p.id,qty:1,rate:p.rate,description:p.name}));input.value='';directTotal();let qty=$('#directItems').lastElementChild.querySelector('.qi-qty');qty.focus();qty.select()};$('#directAddProduct').onchange=add;$('#directAddProduct').onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();add()}};$('#directItems').oninput=directTotal;$('#directItems').onclick=e=>{if(e.target.matches('.qi-remove')){e.target.closest('.item-row').remove();if(!$('#directItems .item-row'))$('#directItems').innerHTML='<div class="empty quote-empty" id="directEmpty">Choose a product to start this sale.</div>';directTotal()}};$('#directItems').onkeydown=e=>{if(e.key==='Enter'&&e.target.matches('.qi-qty')){e.preventDefault();let rate=e.target.closest('.item-row').querySelector('.qi-rate');rate.focus();rate.select()}else if(e.key==='Enter'&&e.target.matches('.qi-rate')){e.preventDefault();$('#directAddProduct').focus()}};$('#directDiscount').oninput=directTotal;$('#saveDirectSale').onclick=async()=>{let rows=[...document.querySelectorAll('#directItems .item-row')],items=rows.map(r=>({product_id:r.querySelector('.qi-product').value,qty:r.querySelector('.qi-qty').value,rate:r.querySelector('.qi-rate').value,description:r.querySelector('.qi-desc').value.trim()})),client_id=$('#directClient').value,discount=$('#directDiscount').value,amount_paid=$('#directPaid').value;if(!client_id)return toast('Select a client first');if(!items.length)return toast('Add at least one product');for(let i=0;i<items.length;i++){if(!items[i].product_id)return toast(`Choose a catalog product for item ${i+1}`);if(!Number(items[i].qty)||Number(items[i].qty)<=0)return toast(`Enter a valid quantity for item ${i+1}`);if(!Number.isFinite(Number(items[i].rate))||Number(items[i].rate)<0)return toast(`Enter a valid rate for item ${i+1}`)}if(!Number.isFinite(Number(discount))||Number(discount)<0)return toast('Discount cannot be negative');if(!Number.isFinite(Number(amount_paid))||Number(amount_paid)<0)return toast('Enter a valid amount received');let btn=$('#saveDirectSale');btn.disabled=true;btn.textContent='Saving…';try{await api('/api/sales',{method:'POST',body:JSON.stringify({client_id,discount,amount_paid,items})});closeModal();state.search='';state.salesFilter='All';await loadAll();nav('sales');toast('Direct sale recorded')}catch(e){btn.disabled=false;btn.textContent='Record sale';toast(e.message)}}}
function directTotal(){let rows=[...document.querySelectorAll('#directItems .item-row')],sub=rows.reduce((a,r)=>a+(Number(r.querySelector('.qi-qty').value)||0)*(Number(r.querySelector('.qi-rate').value)||0),0),discount=Math.min(sub,Math.max(0,Number($('#directDiscount').value)||0));$('#directSubtotal').textContent=money(sub);$('#directDiscShow').textContent=money(discount);$('#directTotal').textContent=money(sub-discount)}
function showSale(sale){let items=sale.items||[],balance=Number(sale.total)-Number(sale.amount_paid);modal(`${esc(sale.number)} · Sale details`,`<div class="payment-context"><b>${esc(sale.client_name)}</b><span>${sale.quotation_number?`${esc(sale.quotation_number)} · Revision ${sale.revision}`:'Direct sale'} · ${esc(sale.sold_at?.slice(0,10)||'')}</span></div><div class="table-wrap"><table><thead><tr><th>Item</th><th>Qty</th><th>Rate</th><th>Amount</th></tr></thead><tbody>${items.length?items.map(i=>`<tr><td><b>${esc(i.product_name||i.name||'Product')}</b>${i.description?`<div class="secondary">${esc(i.description)}</div>`:''}</td><td>${esc(i.qty??i.quantity??'—')} ${esc(i.unit||'')}</td><td>${money(i.rate||0)}</td><td>${money(i.line_total||0)}</td></tr>`).join(''):`<tr><td colspan="4">No item snapshot is available.</td></tr>`}</tbody></table></div><div class="total-box"><div class="total-line"><span>Sale total</span><b>${money(sale.total)}</b></div><div class="total-line"><span>Received</span><b>${money(sale.amount_paid)}</b></div><div class="total-line final"><span>Balance</span><b>${money(balance)}</b></div></div>`,`${cancel}${sale.quotation_id?`<button class="btn" data-action="view-sale-quote" data-id="${sale.quotation_id}">View quotation</button>`:''}<button class="btn primary" data-action="record-payment" data-id="${sale.id}">Record payment</button>`)}
function clientRows(cs){return cs.length?cs.map(c=>`<tr><td><div class="primary-cell">${esc(c.name)}</div><div class="secondary">${esc(c.email||'No email')}</div></td><td>${esc(c.phone)}</td><td>${esc(c.address||'—')}</td><td>${state.quotes.filter(q=>q.client_id===c.id).length}</td><td><button class="btn mini" data-action="edit-client" data-id="${c.id}">Edit</button> <button class="btn mini danger" data-action="delete-client" data-id="${c.id}">Archive</button></td></tr>`).join(''):`<tr><td colspan="5"><div class="empty">No clients found</div></td></tr>`}function clientsPage(){let cs=state.clients.filter(c=>(c.name+c.phone+c.email).toLowerCase().includes(state.search.toLowerCase()));return `${title('CUSTOMER DIRECTORY','Clients','Manage contact details and view quotation history.',state.user.role==='Viewer'?'':button('new-client','＋ &nbsp;Add client','primary'))}<div class="card page-card">${toolbar('Search name, phone, or email')}<div class="table-pad"><table><thead><tr><th>Client</th><th>Phone</th><th>Address</th><th>Quotes</th><th>Actions</th></tr></thead><tbody>${clientRows(cs)}</tbody></table></div></div>`}function productRows(ps){return ps.length?ps.map(p=>`<tr><td><div class="primary-cell">${esc(p.name)}</div><div class="secondary">${esc(p.code)}</div></td><td>${esc(p.category)}</td><td>${esc(p.unit)}</td><td>${money(p.rate)}</td><td>${state.user.role==='Administrator'?`<button class="btn mini" data-action="edit-product" data-id="${p.id}">Edit</button> <button class="btn mini danger" data-action="delete-product" data-id="${p.id}">Archive</button>`:''}</td></tr>`).join(''):`<tr><td colspan="5"><div class="empty">No catalog products</div></td></tr>`}function catalogPage(){let ps=state.products.filter(p=>(p.name+p.code+p.category).toLowerCase().includes(state.search.toLowerCase()));return `${title('PRICE LIST','Catalog & rates','Manage products and current unit selling rates.',state.user.role==='Administrator'?`${button('import-products','↑ &nbsp;Import PDF catalog')}${button('new-product','＋ &nbsp;Add product','primary')}`:'')}<div class="note" style="margin-bottom:15px">Issued quotes preserve their saved rates. Automatic dimensional formulas await workshop approval.</div><div class="card page-card">${toolbar('Search product or code')}<div class="table-pad"><table><thead><tr><th>Product</th><th>Category</th><th>Unit</th><th>Rate</th><th>Actions</th></tr></thead><tbody>${productRows(ps)}</tbody></table></div></div>`}function settingsPage(){return `${title('WORKSPACE','Company settings','Configure business identity and quotation defaults.',button('backup','↓ Download backup'))}<div class="card setting-card"><h2>Company details</h2><p>Displayed on printable customer quotations.</p><div class="form-grid"><div class="field"><label>Company name</label><input class="input" id="setCompany" value="${esc(state.settings.company)}"></div><div class="field"><label>Phone</label><input class="input" id="setPhone" value="${esc(state.settings.phone)}"></div><div class="field"><label>Currency</label><input class="input" id="setCurrency" value="${esc(state.settings.currency)}"></div><div class="field"><label>Default terms</label><input class="input" id="setTerms" value="${esc(state.settings.terms)}"></div></div><button class="btn primary" style="margin-top:14px" data-action="save-settings">Save settings</button></div><div class="card setting-card"><h2>Data storage</h2><p>Business records are stored in the SQLite database on the computer running the server. Download and store regular backups securely.</p><div class="note">Run the application over HTTPS with a managed database before remote internet access.</div></div>`}function usersPage(){return `${title('ACCESS CONTROL','Users & audit','Manage user accounts and review sensitive events.',button('new-user','＋ &nbsp;Add user','primary'))}<div class="card section-card" style="margin-bottom:15px"><div class="section-head"><div><h2>User accounts</h2><p>Server-enforced role access</p></div></div><table><thead><tr><th>Name</th><th>Email</th><th>Role</th><th>Active</th><th></th></tr></thead><tbody>${state.users.map(u=>`<tr><td class="primary-cell">${esc(u.name)}</td><td>${esc(u.email)}</td><td><select class="input" id="role-${u.id}">${['Administrator','Estimator','Sales','Viewer'].map(r=>`<option ${u.role===r?'selected':''}>${r}</option>`).join('')}</select></td><td><select class="input" id="active-${u.id}"><option value="true" ${u.active?'selected':''}>Active</option><option value="false" ${!u.active?'selected':''}>Disabled</option></select></td><td><button class="btn mini" data-action="save-user" data-id="${u.id}">Save</button></td></tr>`).join('')}</tbody></table></div><div class="card section-card"><div class="section-head"><div><h2>Recent audit events</h2></div></div><table><thead><tr><th>When</th><th>User</th><th>Action</th><th>Record</th></tr></thead><tbody>${state.audit.map(a=>`<tr><td>${esc(a.created_at)}</td><td>${esc(a.actor||'—')}</td><td>${esc(a.action)}</td><td>${esc(a.entity_type)} · ${esc(a.entity_id.slice(0,8))}</td></tr>`).join('')}</tbody></table></div>`}
function modal(t,content,foot=''){ $('#modalRoot').innerHTML=`<div class="modal-bg" onclick="if(event.target===this)closeModal()"><div class="modal"><div class="modal-head"><div class="modal-title">${t}</div><button class="x" onclick="closeModal()">×</button></div><div class="modal-body">${content}</div>${foot?`<div class="modal-foot">${foot}</div>`:''}</div></div>`}function closeModal(){$('#modalRoot').innerHTML=''}const cancel='<button class="btn" onclick="closeModal()">Cancel</button>';
function clientModal(c){modal(c?'Edit client':'Add client',`<div class="form-grid"><div class="field" style="grid-column:1/-1"><label>Name *</label><input class="input" id="fName" value="${esc(c?.name||'')}"></div><div class="field"><label>Phone *</label><input class="input" id="fPhone" value="${esc(c?.phone||'')}"></div><div class="field"><label>Email</label><input class="input" id="fEmail" value="${esc(c?.email||'')}"></div><div class="field" style="grid-column:1/-1"><label>Address</label><input class="input" id="fAddress" value="${esc(c?.address||'')}"></div><div class="field" style="grid-column:1/-1"><label>Notes</label><textarea id="fNotes">${esc(c?.notes||'')}</textarea></div></div>`,`${cancel}<button class="btn primary" onclick="saveClient('${c?.id||''}')">Save client</button>`)}async function saveClient(cid){let d={name:$('#fName').value.trim(),phone:$('#fPhone').value.trim(),email:$('#fEmail').value.trim(),address:$('#fAddress').value.trim(),notes:$('#fNotes').value.trim()};try{await api('/api/clients',{method:cid?'PATCH':'POST',body:JSON.stringify(cid?{...d,id:cid}:d)});closeModal();await loadAll();toast('Client saved')}catch(e){toast(e.message)}}
function productModal(p){let categories=[...new Set(['Glass','Mirror','Aluminum profile','Accessories','Services','Other',...state.products.map(x=>x.category)].filter(Boolean))].sort((a,b)=>a.localeCompare(b));modal(p?'Edit product and rate':'Add catalog product',`<form id="productForm" class="product-form" novalidate><div class="product-intro">Add the item details and current selling rate. These details will be available when preparing quotations.</div><div class="form-grid product-grid"><div class="field"><label for="pName">Product name <span>*</span></label><input class="input" id="pName" required maxlength="120" autocomplete="off" placeholder="e.g. Clear tempered glass" value="${esc(p?.name||'')}"><small>Use a clear name your team can recognize.</small></div><div class="field"><label for="pCode">Product code <span>*</span></label><input class="input" id="pCode" required maxlength="100" autocomplete="off" placeholder="e.g. GL-CLR-10" value="${esc(p?.code||'')}"><small id="pCodeHint">Unique reference used to find this product.</small></div><div class="field"><label for="pCategory">Category</label><input class="input" id="pCategory" list="pCategoryOptions" maxlength="80" autocomplete="off" placeholder="Choose or type a category" value="${esc(p?.category||'Other')}"><datalist id="pCategoryOptions">${categories.map(x=>`<option value="${esc(x)}">`).join('')}</datalist><small>Choose an existing category or type a new one.</small></div><div class="field"><label for="pUnit">Selling unit <span>*</span></label><input class="input" id="pUnit" required maxlength="30" list="pUnitOptions" autocomplete="off" placeholder="e.g. sq ft, ft, piece, set" value="${esc(p?.unit||'')}"><datalist id="pUnitOptions"><option value="sq ft"><option value="ft"><option value="piece"><option value="set"><option value="kg"></datalist><small>Quotation quantities will use this unit.</small></div><div class="field product-rate"><label for="pRate">Selling rate (${esc(state.settings.currency||'PKR')}) <span>*</span></label><div class="rate-input"><span>${esc(state.settings.currency||'PKR')}</span><input class="input" id="pRate" type="number" required min="0" step="0.01" inputmode="decimal" placeholder="0.00" value="${esc(p?.rate??'')}"></div><small>Current rate per selected unit.</small></div></div></form>`,`${cancel}<button class="btn primary" id="saveProductBtn" type="button">${p?'Save changes':'Add product'}</button>`);let form=$('#productForm'),name=$('#pName'),code=$('#pCode'),codeHint=$('#pCodeHint'),wasEdited=!!p;code.addEventListener('input',()=>{wasEdited=true});name.addEventListener('input',()=>{if(!wasEdited){let v=name.value.trim().toUpperCase().replace(/[^A-Z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,40);code.value=v;codeHint.textContent=v?'Suggested code — you can edit it.':'Unique reference used to find this product.'}});$('#saveProductBtn').onclick=()=>form.requestSubmit();form.onsubmit=e=>{e.preventDefault();saveProduct(p?.id||'')};name.focus()}async function saveProduct(pid){let form=$('#productForm');if(!form.reportValidity())return;let d={name:$('#pName').value.trim(),code:$('#pCode').value.trim(),category:$('#pCategory').value.trim()||'Other',unit:$('#pUnit').value.trim(),rate:$('#pRate').value};let btn=$('#saveProductBtn');btn.disabled=true;btn.textContent='Saving…';try{await api('/api/products',{method:pid?'PATCH':'POST',body:JSON.stringify(pid?{...d,id:pid}:d)});closeModal();await loadAll();toast('Product and rate saved')}catch(e){btn.disabled=false;btn.textContent=pid?'Save changes':'Add product';toast(e.message)}}
async function importProducts(){modal('Import PDF catalog',`<p class="subtitle">Choose the products JSON prepared from PL 03-04-26.pdf. Existing product codes will be skipped; no existing item or quotation will be changed.</p><div class="field" style="margin-top:16px"><label for="importFile">Catalog JSON file</label><input class="input" id="importFile" type="file" accept=".json,application/json" style="width:100%;height:auto;padding:10px"></div>`,`${cancel}<button class="btn primary" id="uploadCatalog">Import new products</button>`);$('#uploadCatalog').onclick=async()=>{let file=$('#importFile').files?.[0];if(!file)return toast('Choose the catalog JSON file first');let btn=$('#uploadCatalog');btn.disabled=true;btn.textContent='Importing…';try{let payload=JSON.parse(await file.text());if(!Array.isArray(payload.products))throw Error('This file does not contain a products list');let result=await api('/api/products/import',{method:'POST',body:JSON.stringify(payload)});closeModal();await loadAll();toast(`Catalog imported: ${result.added} added, ${result.skipped} already existed`)}catch(e){btn.disabled=false;btn.textContent='Import new products';toast(e.message)}}}
function itemRow(it={}){let p=state.products.find(x=>x.id===it.product_id);return `<div class="item-row"><div class="qi-product-info"><div class="primary-cell">${esc(p?.name||it.product_name||'Product')}</div><div class="secondary">${esc(p?.code||it.code||'')} · ${esc(p?.unit||it.unit||'')}</div><input class="qi-product" type="hidden" value="${esc(it.product_id||'')}"></div><label class="qi-field qi-qty-field"><span>Quantity</span><input class="input qi-qty" aria-label="Quantity" type="number" min="0.001" step="0.001" value="${esc(it.qty||1)}" placeholder="Qty"></label><label class="qi-field qi-rate-field"><span>Rate</span><input class="input qi-rate" aria-label="Rate" type="number" min="0" step="0.01" value="${esc(it.rate??p?.rate??'')}" placeholder="Rate"></label><label class="qi-field qi-desc-field"><span>Specifications / dimensions</span><input class="input qi-desc" aria-label="Specifications or dimensions" value="${esc(it.description||'')}" placeholder="Specifications / dimensions"></label><button type="button" class="btn mini danger qi-remove" aria-label="Remove item">×</button></div>`}function nextNumber(){return 'Assigned on save'}function quoteModal(q){if(!state.clients.length){closeModal();clientModal();return toast('Add a client first')}if(!state.products.length)return toast('Add products and rates first');let cOpts=state.clients.map(c=>`<option value="${c.id}" ${q?.client_id===c.id?'selected':''}>${esc(c.name)}</option>`).join(''),lines=q?.items||[],productOpts=state.products.map(p=>`<option value="${esc(p.name)} · ${esc(p.code)}" label="${esc(p.category)} · ${esc(p.unit)} · ${money(p.rate)}"></option>`).join(''),body=`<div class="form-grid"><div class="field"><label>Client *</label><select class="input" id="qClient"><option value="">Select a client</option>${cOpts}</select></div><div class="field"><label>Quote number</label><input class="input" value="${esc(q?.number||nextNumber())}" disabled></div><div class="field"><label>Valid until</label><input class="input" type="date" id="qValid" value="${esc(q?.valid_until||'')}"></div><div class="field"><label>Fixed discount (${esc(state.settings.currency)})</label><input class="input" type="number" id="qDiscount" min="0" step="0.01" value="${esc(q?.discount||0)}"></div></div><div class="quote-items-head"><b>Items</b></div><div class="field quote-product-picker"><label for="qAddProduct">Product</label><input class="input" id="qAddProduct" list="qProductOptions" autocomplete="off" aria-label="Search product by name or code" placeholder="Type product name or code to search…"><datalist id="qProductOptions">${productOpts}</datalist></div><div class="item-row item-header"><span>PRODUCT</span><span>QTY</span><span>RATE</span><span>SPECIFICATIONS</span><span></span></div><div id="items">${lines.length?lines.map(itemRow).join(''):`<div class="empty quote-empty" id="emptyItems">Choose a product above to start your item list.</div>`}</div><div class="total-box"><div class="total-line"><span>Subtotal</span><b id="qSubtotal">${money(q?.subtotal||0)}</b></div><div class="total-line"><span>Discount</span><b id="qDiscShow">${money(q?.discount||0)}</b></div><div class="total-line final"><span>Total</span><b id="qTotal">${money(q?.total||0)}</b></div></div><div class="field" style="margin-top:14px"><label>Quotation terms</label><textarea id="qTerms">${esc(q?.terms||state.settings.terms||'')}</textarea></div><div class="note" style="margin-top:12px">The total uses quantity × unit rate. Add measurements and workshop specs to the description; automatic cutting and wastage rules await business approval.</div>`;modal(q?'Edit draft quotation':'New quotation',body,`${cancel}<button class="btn primary" id="saveQuote">Save draft</button>`);$('#qClient').value=q?.client_id||'';$('#qAddProduct').onchange=e=>addQuoteProduct(e.target);$('#qAddProduct').onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();addQuoteProduct(e.target)}};$('#items').oninput=updateTotal;$('#items').onkeydown=e=>{if(!['Enter','Tab'].includes(e.key))return;if(e.target.matches('.qi-qty')){e.preventDefault();let rate=e.target.closest('.item-row').querySelector('.qi-rate');rate.focus();rate.select()}else if(e.target.matches('.qi-rate')){e.preventDefault();$('#qAddProduct').focus()}};$('#items').onclick=e=>{if(e.target.matches('.qi-remove')){e.target.closest('.item-row').remove();if(!$('#items .item-row'))$('#items').innerHTML='<div class="empty quote-empty" id="emptyItems">Choose a product above to start your item list.</div>';updateTotal()}};$('#qDiscount').oninput=updateTotal;$('#saveQuote').onclick=()=>saveQuote(q?.id||'');updateTotal()}function addQuoteProduct(input){let value=input.value.trim().toLocaleLowerCase(),p=state.products.find(x=>x.code.toLocaleLowerCase()===value||`${x.name} · ${x.code}`.toLocaleLowerCase()===value);if(!p){if(value)toast('Choose a product from the catalog suggestions');return}$('#emptyItems')?.remove();$('#items').insertAdjacentHTML('beforeend',itemRow({product_id:p.id,qty:1,rate:p.rate,description:p.name}));input.value='';updateTotal();let row=$('#items').lastElementChild,qty=row.querySelector('.qi-qty');qty.focus();qty.select()}function updateTotal(){if(!$('#items'))return;let sub=[...document.querySelectorAll('#items .item-row')].reduce((s,r)=>s+(Number(r.querySelector('.qi-qty').value)||0)*(Number(r.querySelector('.qi-rate').value)||0),0),dis=Math.min(sub,Math.max(0,Number($('#qDiscount').value)||0));$('#qSubtotal').textContent=money(sub);$('#qDiscShow').textContent=money(dis);$('#qTotal').textContent=money(sub-dis)}async function saveQuote(qid){let rows=[...document.querySelectorAll('#items .item-row')],items=rows.map(r=>({product_id:r.querySelector('.qi-product').value,qty:r.querySelector('.qi-qty').value,rate:r.querySelector('.qi-rate').value,description:r.querySelector('.qi-desc').value.trim()})),d={client_id:$('#qClient').value,valid_until:$('#qValid').value,discount:$('#qDiscount').value,terms:$('#qTerms').value,items};if(!d.client_id)return toast('Select a client first');if(!items.length)return toast('Add at least one product');for(let i=0;i<items.length;i++){let item=items[i];if(!item.product_id)return toast(`Choose a catalog product for item ${i+1}`);if(!Number.isFinite(Number(item.qty))||Number(item.qty)<=0)return toast(`Enter a quantity greater than zero for item ${i+1}`);if(!Number.isFinite(Number(item.rate))||Number(item.rate)<0)return toast(`Enter a valid rate for item ${i+1}`)}if(!Number.isFinite(Number(d.discount))||Number(d.discount)<0)return toast('Discount cannot be negative');let btn=$('#saveQuote');if(btn.disabled)return;btn.disabled=true;btn.textContent='Saving…';try{await api(qid?`/api/quotations/${qid}`:'/api/quotations',{method:qid?'PATCH':'POST',body:JSON.stringify(d)});closeModal();state.page='quotes';await loadAll();toast('Draft quotation saved')}catch(e){btn.disabled=false;btn.textContent='Save draft';toast(e.message)}}
function showQuote(q){let body=`<div style="display:flex;justify-content:space-between"><div><div class="eyebrow">${esc(q.number)} · REVISION ${q.revision}</div><h2 style="font-size:18px">${esc(q.client_name)}</h2><div class="secondary">${esc(q.client_phone)} · ${esc(q.client_address)}</div></div>${status(q.status)}</div><div class="table-wrap" style="margin-top:18px"><table><thead><tr><th>Item</th><th>Quantity</th><th>Unit rate</th><th>Amount</th></tr></thead><tbody>${q.items.map(i=>`<tr><td><b>${esc(i.product_name)}</b>${i.description?`<div class="secondary">${esc(i.description)}</div>`:''}</td><td>${esc(i.qty)} ${esc(i.unit)}</td><td>${money(i.rate)}</td><td>${money(i.line_total)}</td></tr>`).join('')}</tbody></table></div><div class="total-box" style="max-width:300px;margin-left:auto"><div class="total-line"><span>Subtotal</span><b>${money(q.subtotal)}</b></div><div class="total-line"><span>Discount</span><b>${money(q.discount)}</b></div><div class="total-line final"><span>Total</span><b>${money(q.total)}</b></div></div><div style="margin-top:14px;font-size:10px;color:#738092"><b>Terms</b><p>${esc(q.terms||'—')}</p>${q.valid_until?`Valid until ${esc(q.valid_until)}`:''}</div>${q.snapshot?`<div class="secondary">Issued and locked: ${esc(q.issued_at||'')}</div>`:''}`;let controls=q.status==='Draft'?`<button class="btn" data-action="edit-quote" data-id="${q.id}">Edit draft</button><button class="btn primary" data-action="issue" data-id="${q.id}">Issue quotation</button>`:q.status==='Issued'?`<button class="btn" data-action="approved" data-id="${q.id}">Mark approved</button><button class="btn" data-action="rejected" data-id="${q.id}">Mark rejected</button><button class="btn" data-action="revision" data-id="${q.id}">Create revision</button>`:q.status==='Approved'?(state.sales.some(s=>s.quotation_id===q.id)?`<button class="btn primary" data-action="goto-sales">View sales register</button><button class="btn" data-action="revision" data-id="${q.id}">Create revision</button>`:`<button class="btn primary" data-action="convert-sale" data-id="${q.id}">Convert to sale</button><button class="btn" data-action="revision" data-id="${q.id}">Create revision</button>`):`<button class="btn" data-action="revision" data-id="${q.id}">Create revision</button>`;modal(`${esc(q.number)} · Quotation`,body,`${cancel}<button class="btn" data-action="pdf" data-id="${q.id}">Print / PDF</button>${controls}`)}
async function convertSale(id){let q=state.quotes.find(x=>x.id===id);if(!q)return;let existing=state.sales.find(s=>s.quotation_id===id);if(existing){nav('sales');return}if(!confirm(`Convert approved quotation ${q.number} for ${q.client_name} into a sale?`))return;try{await api(`/api/quotations/${id}/convert`,{method:'POST',body:'{}'});closeModal();await loadAll();nav('sales');toast('Quotation converted to sale')}catch(e){toast(e.message)}}
async function refreshQuoteModal(qid){try{let q=await api(`/api/quotations/${qid}`);showQuote(q)}catch(e){toast(e.message)}}async function issue(id){if(!confirm('Issue and lock this quotation snapshot?'))return;try{await api(`/api/quotations/${id}/issue`,{method:'POST',body:'{}'});closeModal();await loadAll();toast('Quotation issued and locked')}catch(e){toast(e.message)}}async function setStatus(id,status){try{await api(`/api/quotations/${id}/status`,{method:'POST',body:JSON.stringify({status})});closeModal();await loadAll();toast(`Quotation marked ${status.toLowerCase()}`)}catch(e){toast(e.message)}}async function revise(id){try{let q=await api(`/api/quotations/${id}/revision`,{method:'POST',body:'{}'});closeModal();await loadAll();quoteModal(q)}catch(e){toast(e.message)}}
function printQuote(q){let v=q.snapshot||q,win=window.open('','_blank');if(!win)return toast('Allow pop-ups to print the quotation');win.document.write(`<!doctype html><html><head><meta charset="utf-8"><title>${esc(v.number)}</title><style>body{font:14px Arial;color:#263445;max-width:850px;margin:45px auto;padding:0 25px}header{display:flex;justify-content:space-between;border-bottom:2px solid #377be5;padding-bottom:20px}h1{color:#23436c;margin:0 0 5px}small{color:#718094}.meta{display:flex;justify-content:space-between;margin:25px 0}.meta div{line-height:1.8}table{width:100%;border-collapse:collapse;margin-top:22px}th,td{text-align:left;padding:12px;border-bottom:1px solid #e5e9ed}th{font-size:11px;text-transform:uppercase;color:#778392}.totals{width:300px;margin:20px 0 0 auto}.totals div{display:flex;justify-content:space-between;padding:7px}.grand{font-size:18px;font-weight:bold;border-top:1px solid #ccd4dd}.terms{margin-top:34px;color:#566273;line-height:1.6}.footer{margin-top:40px;border-top:1px solid #e5e9ed;padding-top:12px;color:#8c98a5;font-size:11px}@media print{body{margin:20px auto}}</style></head><body><header><div><h1>${esc(state.settings.company)}</h1><small>${esc(state.settings.phone)}</small></div><div style="text-align:right"><h2>QUOTATION</h2><b>${esc(v.number)}</b><div><small>${esc(q.created_at?.slice(0,10)||'')}</small></div></div></header><div class="meta"><div><b>Prepared for</b><br>${esc(v.client_name)}<br>${esc(v.client_phone)}<br>${esc(v.client_address)}</div><div><b>Status</b><br>${esc(q.status)}${v.valid_until?`<br><b>Valid until</b><br>${esc(v.valid_until)}`:''}</div></div><table><thead><tr><th>Description</th><th>Quantity</th><th>Unit rate</th><th>Amount</th></tr></thead><tbody>${v.items.map(i=>`<tr><td><b>${esc(i.product_name)}</b>${i.description?`<br><small>${esc(i.description)}</small>`:''}</td><td>${esc(i.qty)} ${esc(i.unit)}</td><td>${money(i.rate)}</td><td>${money(i.line_total)}</td></tr>`).join('')}</tbody></table><div class="totals"><div><span>Subtotal</span><b>${money(v.subtotal)}</b></div><div><span>Discount</span><b>${money(v.discount)}</b></div><div class="grand"><span>Total</span><b>${money(v.total)}</b></div></div><div class="terms"><b>Terms & conditions</b><br>${esc(v.terms||'')}</div><div class="footer">${esc(state.settings.company)} · ${esc(v.number)}</div><script>window.onload=()=>setTimeout(()=>window.print(),250)<\/script></body></html>`);win.document.close()}
function download(data,name,type){let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([data],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}async function backup(){try{let r=await fetch('/api/backup');if(!r.ok)throw Error((await r.json()).error);download(await r.text(),'frameflow-backup.json','application/json')}catch(e){toast(e.message)}}async function exportCsv(){let rows=[['Number','Date','Client','Status','Subtotal','Discount','Total','Currency'],...state.quotes.map(q=>[q.number,q.created_at,q.client_name,q.status,q.subtotal,q.discount,q.total,q.currency])];download(rows.map(r=>r.map(x=>'"'+String(x??'').replaceAll('"','""')+'"').join(',')).join('\r\n'),'quotations.csv','text/csv')}function exportSalesCsv(sales,name){let rows=[['Sale','Date','Client','Quotation','Revision','Status','Total','Received','Balance','Currency'],...sales.map(s=>[s.number,s.sold_at,s.client_name,s.quotation_number,s.revision,s.payment_status,s.total,s.amount_paid,Number(s.total)-Number(s.amount_paid),s.currency])];download(rows.map(r=>r.map(x=>'"'+String(x??'').replaceAll('"','""')+'"').join(',')).join('\r\n'),name,'text/csv')}function exportReportCsv(){let {start,end}=reportRange();exportSalesCsv(filteredReportSales(),`sales-report-${start}-to-${end}.csv`)}
function newUserModal(){modal('Create user',`<div class="form-grid"><div class="field"><label>Name</label><input class="input" id="uName"></div><div class="field"><label>Email</label><input class="input" id="uEmail" type="email"></div><div class="field"><label>Role</label><select class="input" id="uRole">${['Estimator','Sales','Viewer','Administrator'].map(x=>`<option>${x}</option>`).join('')}</select></div><div class="field"><label>Temporary password (12+ characters)</label><input class="input" id="uPassword" type="password"></div></div>`,`${cancel}<button class="btn primary" data-action="create-user">Create account</button>`)}
let deferredInstallPrompt=null;const installButton=$('#installApp');if(('serviceWorker'in navigator)&&location.protocol!=='file:')window.addEventListener('load',()=>navigator.serviceWorker.register('/service-worker.js').catch(()=>{}));if(window.matchMedia?.('(display-mode: standalone)').matches||navigator.standalone)installButton.hidden=true;window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();deferredInstallPrompt=e;installButton.hidden=false});window.addEventListener('appinstalled',()=>{installButton.hidden=true;deferredInstallPrompt=null;toast('FrameFlow installed')});function installHelp(){let ios=/iphone|ipad|ipod/i.test(navigator.userAgent),secure=window.isSecureContext;if(!secure)return modal('Install FrameFlow','<p>For mobile installation, open the deployed HTTPS app link on your phone.</p>',cancel);let message=ios?'<p>In Safari, tap <b>Share</b>, then choose <b>Add to Home Screen</b>.</p>':'<p>Open your browser menu and choose <b>Install app</b> or <b>Add to Home screen</b>.</p>';modal('Install FrameFlow',`${message}<p>The installed app needs an internet connection to load your live business records.</p>`,cancel)}async function installPwa(){if(!deferredInstallPrompt)return installHelp();deferredInstallPrompt.prompt();let choice=await deferredInstallPrompt.userChoice;deferredInstallPrompt=null;if(choice?.outcome==='accepted'){installButton.hidden=true;toast('FrameFlow added to your device')}else toast('Installation was cancelled')}
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('#modalRoot').innerHTML){closeModal();return}if(e.altKey&&e.key.toLowerCase()==='n'&&state.user&&state.user.role!=='Viewer'&&!document.querySelector('.modal-bg')){e.preventDefault();quoteModal();return}if(e.key==='/'&&!e.ctrlKey&&!e.metaKey&&!e.altKey&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)&&!document.querySelector('.modal-bg')){let search=$('#search');if(search){e.preventDefault();search.focus()}}});
document.addEventListener('input',e=>{if(e.target.id==='search'){state.search=e.target.value;render()} });document.addEventListener('change',e=>{if(e.target.id==='statusFilter'){state.filter=e.target.value;render()}if(e.target.id==='quoteSort'){state.quoteSort=e.target.value;render()}if(e.target.id==='reportPeriod'){state.reportPeriod=e.target.value;render()}if(e.target.id==='reportClient'){state.reportClient=e.target.value;render()}if(e.target.id==='reportPayment'){state.reportPayment=e.target.value;render()}if(e.target.id==='reportSource'){state.reportSource=e.target.value;render()}if(e.target.id==='reportStart'||e.target.id==='reportEnd'){state.reportPeriod='custom';state.reportStart=$('#reportStart').value;state.reportEnd=$('#reportEnd').value;render()}if(e.target.id==='salesFilter'){state.salesFilter=e.target.value;render()}});document.addEventListener('click',async e=>{let go=e.target.closest('[data-goto]');if(go)return nav(go.dataset.goto);let quoteFilter=e.target.closest('[data-quote-filter]');if(quoteFilter){state.filter=quoteFilter.dataset.quoteFilter;render();return}let b=e.target.closest('[data-action]');if(!b)return;let a=b.dataset.action,id=b.dataset.id;try{if(a==='goto-reports')nav('reports');if(a==='goto-sales')nav('sales');if(a==='view-sale-quote')showQuote(state.quotes.find(q=>q.id===id));if(a==='record-payment'){let sale=state.sales.find(x=>x.id===id);if(sale)paymentModal(sale)}if(a==='view-sale'){let sale=state.sales.find(x=>x.id===id);if(sale)showSale(sale)}if(a==='new-direct-sale')directSaleModal();if(a==='install-app')await installPwa();if(a==='convert-sale')await convertSale(id);if(a==='new-client')clientModal();if(a==='edit-client')clientModal(state.clients.find(x=>x.id===id));if(a==='delete-client'){if(confirm('Archive this client?')){await api('/api/clients?id='+encodeURIComponent(id),{method:'DELETE'});await loadAll();toast('Client archived')}}if(a==='import-products')importProducts();if(a==='new-product')productModal();if(a==='edit-product')productModal(state.products.find(x=>x.id===id));if(a==='delete-product'){if(confirm('Archive this product from new quotations?')){await api('/api/products?id='+encodeURIComponent(id),{method:'DELETE'});await loadAll();toast('Product archived')}}if(a==='new-quote')quoteModal();if(a==='view-quote')showQuote(state.quotes.find(x=>x.id===id));if(a==='edit-quote'){let q=state.quotes.find(x=>x.id===id);if(q)quoteModal(q)}if(a==='issue')await issue(id);if(a==='approved')await setStatus(id,'Approved');if(a==='rejected')await setStatus(id,'Rejected');if(a==='revision')await revise(id);if(a==='pdf')printQuote(state.quotes.find(x=>x.id===id));if(a==='backup')await backup();if(a==='export')exportCsv();if(a==='export-sales')exportSalesCsv(visibleSales(),'sales-register.csv');if(a==='export-report')exportReportCsv();if(a==='save-settings'){let d={company:$('#setCompany').value.trim(),phone:$('#setPhone').value.trim(),currency:$('#setCurrency').value.trim().toUpperCase(),terms:$('#setTerms').value.trim()};await api('/api/settings',{method:'PATCH',body:JSON.stringify(d)});await loadAll();toast('Settings saved')}if(a==='logout'){await api('/api/auth/logout',{method:'POST',body:'{}'});state.user=null;showLogin()}if(a==='new-user')newUserModal();if(a==='create-user'){let d={name:$('#uName').value,email:$('#uEmail').value,password:$('#uPassword').value,role:$('#uRole').value};await api('/api/users',{method:'POST',body:JSON.stringify(d)});closeModal();await loadAll();toast('User created')}if(a==='save-user'){let role=$(`#role-${id}`).value,active=$(`#active-${id}`).value==='true';await api('/api/users',{method:'PATCH',body:JSON.stringify({id,role,active})});await loadAll();toast('Permissions updated')}}catch(err){toast(err.message)}});boot();



